import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ToastProvider } from './components/Toast';

// Layout
import Layout from './pages/Layout';

// Pages publiques
import Landing       from './pages/Landing';
import Auth          from './pages/Auth';
import NotFound      from './pages/NotFound';

// Pages étudiant
import EtudiantDashboard from './pages/EtudiantDashboard';
import Profs             from './pages/Profs';
import Favoris           from './pages/Favoris';
import MesReservations   from './pages/MesReservations';
import Profile           from './pages/Profile';

// Pages professeur
import ProfDashboard  from './pages/ProfDashboard';
import Disponibilites from './pages/Disponibilites';

// Pages admin
import Admin from './pages/Admin';

// Chatbot
import Chatbot from './pages/Chatbot';

/* ── Garde de route ── */
function PrivateRoute({ children, roles }) {
  const { user, loading } = useAuth();
  if (loading) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', color: 'var(--text2)' }}>
      <div style={{ textAlign: 'center' }}>
        <div style={{ fontSize: '2rem', marginBottom: 12, animation: 'spin 1s linear infinite' }}>⏳</div>
        <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
        Chargement...
      </div>
    </div>
  );
  if (!user) return <Navigate to="/login" replace />;
  if (roles && !roles.includes(user.role)) return <Navigate to="/" replace />;
  return children;
}

/* ── Route publique (redirige si connecté) ── */
function PublicRoute({ children }) {
  const { user, loading } = useAuth();
  if (loading) return null;
  if (user) {
    const home = user.role === 'professeur' ? '/prof'
               : user.role === 'admin'      ? '/admin'
               : '/';
    return <Navigate to={home} replace />;
  }
  return children;
}

/* ── Route d'accueil (landing si non connecté, dashboard si connecté) ── */
function HomeRoute() {
  const { user, loading } = useAuth();
  if (loading) return null;
  if (!user) return <Landing />;
  // Connecté → dashboard selon le rôle
  if (user.role === 'étudiant')   return <EtudiantDashboard />;
  if (user.role === 'professeur') return <Navigate to="/prof"  replace />;
  if (user.role === 'admin')      return <Navigate to="/admin" replace />;
  return <Landing />;
}

export default function App() {
  return (
    <AuthProvider>
      <ToastProvider>
        <BrowserRouter>
          <Routes>

            {/* ── Routes publiques (sans layout) ── */}
            <Route path="/login"    element={<PublicRoute><Auth mode="login"    /></PublicRoute>} />
            <Route path="/register" element={<PublicRoute><Auth mode="register" /></PublicRoute>} />

            {/* ── Routes avec layout ── */}
            <Route element={<Layout />}>

              {/* Accueil : landing (public) ou dashboard (connecté) */}
              <Route path="/" element={<HomeRoute />} />

              {/* ── Étudiant ── */}
              <Route path="/profs"
                element={<PrivateRoute roles={['étudiant', 'admin']}><Profs /></PrivateRoute>}
              />
              <Route path="/favoris"
                element={<PrivateRoute roles={['étudiant']}><Favoris /></PrivateRoute>}
              />
              <Route path="/reservations"
                element={<PrivateRoute roles={['étudiant']}><MesReservations /></PrivateRoute>}
              />
              <Route path="/chatbot"
                element={<PrivateRoute roles={['étudiant']}><Chatbot /></PrivateRoute>}
              />

              {/* ── Professeur ── */}
              <Route path="/prof"
                element={<PrivateRoute roles={['professeur']}><ProfDashboard /></PrivateRoute>}
              />
              <Route path="/dispos"
                element={<PrivateRoute roles={['professeur']}><Disponibilites /></PrivateRoute>}
              />

              {/* ── Admin ── */}
              <Route path="/admin"
                element={<PrivateRoute roles={['admin']}><Admin /></PrivateRoute>}
              />

              {/* ── Commun ── */}
              <Route path="/profil"
                element={<PrivateRoute roles={['étudiant', 'professeur', 'admin']}><Profile /></PrivateRoute>}
              />

              {/* ── 404 ── */}
              <Route path="*" element={<NotFound />} />
            </Route>

          </Routes>
        </BrowserRouter>
      </ToastProvider>
    </AuthProvider>
  );
}
